package main
/*
#include "quantile.h"
#include <stdlib.h>
*/
import "C"
import (
  "fmt"
  "unsafe"
)
func ComputeQuantiles(data []float64, k int) ([]float64, error) {
  if k <= 0 { return nil, fmt.Errorf("k must be >0") }
  n := len(data)
  if n == 0 { return nil, fmt.Errorf("data empty") }
  out := make([]float64, k)
