  C.compute_quantiles((*C.double)(unsafe.Pointer(&data[0])), C.size_t(n), (*C.double)(unsafe.Pointer(&out[0])), C.size_t(k), &status)
  if status != 0 { return nil, fmt.Errorf("quantiles failed, status=%d", status) }
  return out, nil
}
